export function listPredictivePlanningMemories(): PantavionPredictivePlanningMemoryRecord[] {
  const commitments = listCommitments()
    .filter((item) => item.status === 'scheduled' || item.status === 'open' || item.status === 'ready')
    .map((item, index) => ({
